initial_condition:
with {
    the SUT containing a ImplicitlyCreated @context created from a subscription query.
            }

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete a @context with Response Status Code set to 400     and
        Delete a @context with Response reason set to 'Bad Request'     and
        Delete a @context with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/BadRequestData' and Response Body Title is a string and is not ${EMPTY} and Response Body Detail is a string and is not ${EMPTY} and Response Boty Title is not equal to Response Body Detail
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/jsonldContexts/{contextId}'
        method set to 'DELETE'
        Delete a @context whose 'URI' set to '${implicit_id}'
}
